selector_to_html = {"a[href=\"references/operators.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Operator List<a class=\"headerlink\" href=\"#operator-list\" title=\"Link to this heading\">#</a></h1>", "a[href=\"#contact-us\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Contact Us<a class=\"headerlink\" href=\"#contact-us\" title=\"Link to this heading\">#</a></h2><p>If you have any questions about our project, please submit an issue, or contact us through <a class=\"reference external\" href=\"mailto:flaggems%40baai.ac.cn\">flaggems<span>@</span>baai<span>.</span>ac<span>.</span>cn</a>.</p><p>We also created WeChat group for FlagGems. Scan the QR code to join the group chat! To get the first hand message about our updates and new release, or having any questions or ideas, join us now!</p>", "a[href=\"overview/features.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Features Overview<a class=\"headerlink\" href=\"#features-overview\" title=\"Link to this heading\">#</a></h1><h2>Rich Collection of Operators<a class=\"headerlink\" href=\"#rich-collection-of-operators\" title=\"Link to this heading\">#</a></h2><p>FlagGems features a large collection of PyTorch compatible operators.\nRefer to <a class=\"reference internal\" href=\"references/operators.html\"><span class=\"doc std std-doc\">operator supported</span></a> and\n<a class=\"reference internal\" href=\"references/experimental.html\"><span class=\"doc std std-doc\">experimental operators</span></a>\nfor list of formally supported operators and experimental operators.</p>", "a[href=\"#next-step\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Next Step<a class=\"headerlink\" href=\"#next-step\" title=\"Link to this heading\">#</a></h2>", "a[href=\"overview/platforms.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Platforms Supported<a class=\"headerlink\" href=\"#platforms-supported\" title=\"Link to this heading\">#</a></h1><p><em>FlagGems</em> supports 10+ backends. The currently supported platforms and\ntheir capabilities are listed blow:</p>", "a[href=\"#supported-models\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Supported Models<a class=\"headerlink\" href=\"#supported-models\" title=\"Link to this heading\">#</a></h2>", "a[href=\"getting-started/install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Installing FlagGems<a class=\"headerlink\" href=\"#installing-flaggems\" title=\"Link to this heading\">#</a></h1><h2>1. Prerequisites<a class=\"headerlink\" href=\"#prerequisites\" title=\"Link to this heading\">#</a></h2>", "a[href=\"references/changelog.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Change History<a class=\"headerlink\" href=\"#change-history\" title=\"Link to this heading\">#</a></h1><h2>v5.4<a class=\"headerlink\" href=\"#v5-4\" title=\"Link to this heading\">#</a></h2><p><strong>Release date</strong>: 2026-09-28</p>", "a[href=\"#about-flaggems\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">About FlagGems<a class=\"headerlink\" href=\"#about-flaggems\" title=\"Link to this heading\">#</a></h2><p><em>FlagGems</em> is a high-performance general operator library implemented in the <a class=\"reference external\" href=\"https://github.com/openai/triton\">Triton</a> language. It aims to provide a suite of kernel functions to accelerate LLM training and inference.</p><p>By registering with the ATen backend of PyTorch, <em>FlagGems</em> facilitates a seamless transition, allowing users to switch to the Triton function library without the need to modify their model code.</p>", "a[href=\"#contribution\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Contribution<a class=\"headerlink\" href=\"#contribution\" title=\"Link to this heading\">#</a></h2><p>If you are interested in contributing to the FlagGems project, please refer to the <a class=\"reference internal\" href=\"contribution/overview.html\"><span class=\"doc std std-doc\">contributing guide</span></a> page. Any kind of contributions would be highly appreciated.</p>", "a[href=\"#flaggems-overview\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagGems Overview<a class=\"headerlink\" href=\"#flaggems-overview\" title=\"Link to this heading\">#</a></h1><p><a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems\"><a data-lightbox=\"image-set\" href=\"https://img.shields.io/badge/GitHub-flagos--ai/FlagGems-blue\">\n<img alt=\"GitHub\" src=\"https://img.shields.io/badge/GitHub-flagos--ai/FlagGems-blue\"/></a>\n</a>\n<a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagGems/blob/master/LICENSE\"><a data-lightbox=\"image-set\" href=\"https://img.shields.io/badge/License-Apache%202.0-green\">\n<img alt=\"License\" src=\"https://img.shields.io/badge/License-Apache%202.0-green\"/></a>\n</a></p>", "a[href=\"contribution/overview.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h1><p>In pull requests, contributor should describe what changed and why.\nPlease also provide test cases if applicable.\nPull requests require approvals from <strong>one member</strong> before merging.\nAdditionally, they must pass continuous integration checks.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
